// === Tab: mySketch.js ===
let theShader;

function preload(){
  theShader = loadShader('https://openprocessing.org/sketch/1590234/files/shader.vert', 'shader.frag');
}

function setup() {
	pixelDensity(1.0);
  createCanvas(3840,2160, WEBGL);
}

function draw() {
  shader(theShader);

  theShader.setUniform("u_resolution", [width, height]);
  theShader.setUniform("u_time", millis() / 1000.0);

  quad(-1, -1, 1, -1, 1, 1, -1, 1);
}

